from pathlib import Path
import flet as ft 
import asyncio

ASSETS_DIR = Path(__file__).resolve().parent / "assets"


def main(page: ft.Page):
    page.title = "Image Example"
    page.scroll = "auto"
    # page.vertical_alignment = ft.MainAxisAlignment.CENTER
    
    progress_bar = ft.ProgressBar(
        width=400, 
        value=0.0,
        color=ft.Colors.BLUE,
        bgcolor=ft.Colors.BLUE_GREY_100
        )
    
    progress_ring = ft.ProgressRing(
        width=100,
        height=100,
        stroke_width=10,
        value=0.5,
        color=ft.Colors.BLUE_600,
    )
    
    async def update_progress():
        for i in range(101):
            progress_bar.value = i / 100
            progress_ring.value = i / 100
            page.update()
            await asyncio.sleep(0.1)

    # Create an Image control
    image_url = "data:image/webp;base64,"
    
    image = ft.Image(
        src=image_url, width=700, height=300
    )

    # Add the Image control to the page
    page.add(
        image,
        ft.Image(
            src="download.webp", width=700, height=300
        ),
        ft.Image(
            src="download (1).webp", width=700, height=300
        ),
        ft.Image(
            src="icon.png",
            width=200,
            height=200
        ),
        ft.CircleAvatar(
            foreground_image_src="download.webp",
            radius=100
        ),
        ft.Text("Loading...", size=30),
        
        progress_bar,
        progress_ring,
        
        
    )
    page.run_task(update_progress)
    
    
ft.run(main)